MAP
    NAME "SS_MAP_GRAL_CURVAS_MUNICIPIO"
    INCLUDE 'includes/globals.map'
    WEB
        INCLUDE "includes/temp_directory.map"
        METADATA
            INCLUDE 'includes/common_metadata.map'
        END #METADATA
    END #WEB
    CONFIG "MS_ERRORFILE" "/srv/mapserver/err_curvas_desnivel.log"
    DEBUG 0
    LAYER
        CONNECTIONTYPE POSTGIS
        NAME "SS_MAP_GRAL_CURVAS_MUNICIPIO"
        PROJECTION
			'init=epsg:32614'
		END #PROJECTION
        INCLUDE 'includes/conexionGeo.map'
        DATA "geometry from curvas_municipio using unique gid using srid=32614"
        STATUS DEFAULT
        TYPE line
        LABELCACHE ON
        MAXSCALE 50000
        LABELITEM "z"
        CLASS
            NAME "Curvas de Nivel"
            STYLE
                SYMBOL 'plainline'
                size 2
                COLOR 0 0 0
            END #STYLE
            LABEL
                TYPE TRUETYPE
                FONT 'arial'
                SIZE 19
                COLOR 0 0 0
                OUTLINECOLOR 254 254 254
            END #LABEL
        END #CLASS
    END #LAYER
END #MAP